// Des: Tests for ru-reci-main: phrase parse, dry run sends 0, price recipe, bulk guard
// Flo: parse phrases > run recipes on the mock chat page > assert counts and page state
// I/O: phrases and html > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const rec = @import("ru-reci-main.zig"); const sess = @import("ru-sess-ctxz.zig"); const data = @import("st-stat-data.zig"); const conf = @import("cf-conf-load.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing;
const NOON: i64 = 100 * 86400000 + 12 * 3600000;
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
fn cfgOf() conf.Conf { var cfg: conf.Conf = .{}; cfg.type_dely_msec = .{ 1, 2 }; cfg.warm_dayz_coun = 0; cfg.retr_coun_maxz = 2; return cfg; }
const Rig = struct { tmpz: std.testing.TmpDir, mok: mock.Mock, aren: std.heap.ArenaAllocator, sto: data.Stor,
fn up(self: *Rig, buff: []u8) !void { self.tmpz = std.testing.tmpDir(.{}); self.mok = try mock.start(T.allocator, T.io, try profOf(&self.tmpz, buff), fixt.chat); self.aren = std.heap.ArenaAllocator.init(T.allocator); self.sto = try data.Stor.open(T.allocator, ":memory:"); }
fn down(self: *Rig) void { self.sto.close(); self.aren.deinit(); self.mok.stop(); self.tmpz.cleanup(); }
fn ses(self: *Rig, cfg: conf.Conf, mode: sess.Mode) sess.Sess { var out = sess.Sess.init(T.allocator, T.io, self.aren.allocator(), cfg, &self.sto, self.mok.conn, mode); out.fast = true; out.fake_ms = NOON; out.job = "reci"; return out; }
fn js(self: *Rig, code: []const u8) ![]const u8 { return snap.evalStr(self.aren.allocator(), self.mok.conn, code); } };
test "parse send in English and Vietnamese" { const one = try rec.parse("Send Mom: see you at 7"); try T.expectEqualStrings("Mom", one.send.chat); try T.expectEqualStrings("see you at 7", one.send.text); const two = try rec.parse("  gửi Bố: ok nhé "); try T.expectEqualStrings("Bố", two.send.chat); try T.expectEqualStrings("ok nhé", two.send.text); }
test "parse remind with at and to, with colon, with Vietnamese, with no title" { const one = try rec.parse("Remind Mom at 8 to buy milk"); try T.expectEqualStrings("Mom", one.remind.chat); try T.expectEqualStrings("8", one.remind.whenz); try T.expectEqualStrings("buy milk", one.remind.titl); const two = try rec.parse("remind Boss at 20:00: call back"); try T.expectEqualStrings("20:00", two.remind.whenz); try T.expectEqualStrings("call back", two.remind.titl); const three = try rec.parse("nhắc Mẹ lúc 8h để gọi điện"); try T.expectEqualStrings("Mẹ", three.remind.chat); try T.expectEqualStrings("gọi điện", three.remind.titl); const four = try rec.parse("remind Mom at 9am"); try T.expectEqualStrings("9am", four.remind.whenz); try T.expectEqualStrings("Reminder", four.remind.titl); }
test "parse fixed phrases and rejects junk" { try T.expect((try rec.parse("Answer price questions")) == .price); try T.expect((try rec.parse("summarize UNREAD")) == .summ); try T.expectError(error.BadJob, rec.parse("dance for me")); try T.expectError(error.BadJob, rec.parse("send Mom")); try T.expectError(error.BadJob, rec.parse("send : hi")); try T.expectError(error.BadJob, rec.parse("remind Mom")); try T.expectError(error.BadJob, rec.parse("remind  at 8")); try T.expectError(error.BadJob, rec.parse("")); }
test "M5 gate: dry reply recipe prints a preview and sends 0" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); var ses = rig.ses(cfgOf(), .dry); const rp = try rec.run(&ses, try rec.parse("send Mom: hello")); try T.expectEqual(@as(u32, 1), rp.prev); try T.expectEqual(@as(u32, 0), rp.sent); try T.expectEqualStrings("0", try rig.js("sent.length")); }
test "live send and remind recipes work through the session" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); var ses = rig.ses(cfgOf(), .live); const one = try rec.run(&ses, try rec.parse("send Mom: hello")); try T.expectEqual(@as(u32, 1), one.sent); const two = try rec.run(&ses, try rec.parse("remind Mom at 8 to buy milk")); try T.expectEqual(@as(u32, 1), two.sent); try T.expectEqualStrings("buy milk|8", try rig.js("rems[0]")); }
test "summarize unread lists last message and sends nothing" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); var ses = rig.ses(cfgOf(), .read); const rp = try rec.run(&ses, .summ); try T.expectEqual(@as(u32, 1), rp.prev); try T.expectEqualStrings("Mom: Dinner at 7?", rp.lines[0]); try T.expectEqualStrings("0", try rig.js("sent.length")); }
test "price recipe: no template skips, template previews in dry and sends in live" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); _ = try rig.js("D.Mom.push('them|What is the price?')"); var none = rig.ses(cfgOf(), .dry); const skp = try rec.run(&none, .price); try T.expectEqual(@as(u32, 1), skp.skip); try T.expectEqual(@as(u32, 0), skp.prev); var cfg = cfgOf(); cfg.reci_pric_text = "It is 100k."; var dry = rig.ses(cfg, .dry); dry.fake_ms = NOON + 100000; const prv = try rec.run(&dry, .price); try T.expectEqual(@as(u32, 1), prv.prev); try T.expectEqualStrings("0", try rig.js("sent.length")); var live = rig.ses(cfg, .live); live.fake_ms = NOON + 200000; const snt = try rec.run(&live, .price); try T.expectEqual(@as(u32, 1), snt.sent); try T.expectEqualStrings("Mom|It is 100k.", try rig.js("sent[0]")); }
test "price recipe ignores chats without a price word" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); var cfg = cfgOf(); cfg.reci_pric_text = "x"; var live = rig.ses(cfg, .live); const rp = try rec.run(&live, .price); try T.expectEqual(@as(u32, 0), rp.sent + rp.prev + rp.skip); }
test "bulk guard: live over the limit needs force" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); _ = try rig.js("D.Mom.push('them|giá bao nhiêu?')"); var cfg = cfgOf(); cfg.reci_pric_text = "ok"; cfg.reci_bulk_maxz = 0; var live = rig.ses(cfg, .live); try T.expectError(error.NeedForce, rec.run(&live, .price)); try T.expectEqualStrings("0", try rig.js("sent.length")); }
test "template fills {name} and keeps everything else" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectEqualStrings("Chào Mom, giá 100k {x} Mom", try rec.fill(aren.allocator(), "Chào {name}, giá 100k {x} {name}", "Mom")); try T.expectEqualStrings("", try rec.fill(aren.allocator(), "", "Mom")); try T.expectEqualStrings("no var", try rec.fill(aren.allocator(), "no var", "Mom")); }
test "price reply uses the template with the chat name; AI over its daily cap falls back to the template" { var buff: [160]u8 = undefined; var rig: Rig = undefined; try rig.up(&buff); defer rig.down(); _ = try rig.js("D.Mom.push('them|what is the price?')"); var cfg = cfgOf(); cfg.reci_pric_text = "Hi {name}, it is 100k."; cfg.smar_mode_enab = true; cfg.smar_calls_dayz = 0; cfg.smar_clau_exec = "zz-no-such-ai-tool"; cfg.smar_llam_exec = "zz-no-such-ai-tool2"; var ses = rig.ses(cfg, .live); const rep = try rec.run(&ses, .price); try T.expectEqual(@as(u32, 1), rep.sent); try T.expectEqualStrings("Mom|Hi Mom, it is 100k.", try rig.js("sent[0]")); try T.expectEqual(@as(u32, 0), try rig.sto.kindSince("ai", 0)); }
